import Foundation
import Testing
@testable import HopwatchGUI

/// `link.offline` was declared on `MonitorSample.Link` but never read by its
/// lenient decoder, so the running app never had it and the offline card's
/// "Offline for X · last on Y" and precursor copy never appeared. These decode
/// lines in the exact shape `helpers/monitor_sample.py` emits (generated with
/// it, not hand-written), and pin how the card degrades when the monitor does
/// not know a piece of the context.
@Suite struct OfflineContextTests {

    /// Generated by `helpers/monitor_sample.py` with the `NETDIAG_MON_OFFLINE_*`
    /// variables below; only the `offline` object is swapped per test.
    static let offlineObject = #"{"reason":"wifi-not-joined","reason_label":"Not connected","down_since":"2026-10-12T10:00:00Z","down_duration_s":60,"last_network":"Home","precursor":"router-unreachable","precursor_summary":"Your router stopped responding right before Wi-Fi dropped, which usually means it restarted."}"#

    static func line(offline: String, up: Bool = false) -> String {
        #"{"schema":2,"version":"1.15.1","ts":"2026-10-12T10:01:00Z","seq":3,"gap_s":null,"refreshed":[],"link":{"up":\#(up),"interface":null,"type":null,"ip":null,"gateway":null,"gateway_mac":null,"ssid":null,"bssid":null,"offline":\#(offline)},"network":{"id":null,"label":null,"group_id":null},"vpn":{"active":false,"type":null,"name":null},"gateway":{"loss_pct":null,"rtt_avg_ms":null,"rtt_jitter_ms":null},"internet":{"loss_pct":null,"rtt_avg_ms":null,"rtt_jitter_ms":null},"jitter_ms":null,"wifi":null,"dns":{"ok":null,"resolver":null,"elapsed_ms":null,"local_fail":null,"local":null},"tcp":{"any_ok":null,"targets":[]},"public":{"ok":null,"ip":null,"isp":null,"asn":null,"city":null,"country":null,"country_iso":null,"captive_portal":null},"status":{"severity":"ok","rules":["N1","WJ-1"],"measurement":"unknown","icmp_filtered":false,"degraded":false,"paused":false,"cadence_s":null,"auto_reconnect":null,"carry":null,"carry_network":"Home"}}"#
    }

    static func decode(_ json: String) throws -> MonitorSample {
        try JSONDecoder().decode(MonitorSample.self, from: Data(json.utf8))
    }

    @Test func fullBlockDecodes() throws {
        let s = try Self.decode(Self.line(offline: Self.offlineObject))
        let off = try #require(s.link.offline)
        #expect(off.reason == "wifi-not-joined")
        #expect(off.downSince == "2026-10-12T10:00:00Z")
        #expect(off.downDurationS == 60)
        #expect(off.lastNetwork == "Home")
        #expect(off.precursor == "router-unreachable")
        // Prose the CLI wrote, decoded as it came: the app composes none of it.
        #expect(off.precursorSummary
                == "Your router stopped responding right before Wi-Fi dropped, which usually means it restarted.")
        #expect(off.statusLine == "Offline for 1m · last on Home")
        // A sample that decodes also keeps everything else.
        #expect(s.link.up == false)
        #expect(s.status.rules == ["N1", "WJ-1"])
    }

    @Test func nullBlockOnALinkUpSampleStaysNil() throws {
        let s = try Self.decode(Self.line(offline: "null", up: true))
        #expect(s.link.up)
        #expect(s.link.offline == nil)
    }

    @Test func missingBlockNeverDropsTheSample() throws {
        let json = Self.line(offline: Self.offlineObject)
            .replacingOccurrences(of: #","offline":\#(Self.offlineObject)"#, with: "")
        let s = try Self.decode(json)
        #expect(s.link.offline == nil)
        #expect(s.status.rules == ["N1", "WJ-1"])
    }

    @Test func monitorRestartShapeHasNoLastNetworkOrPrecursor() throws {
        // What a process that starts already offline emits: the shape the
        // monitor produces with NETDIAG_MON_OFFLINE_LAST_NETWORK unset.
        let obj = #"{"reason":"wifi-not-joined","down_since":"2026-10-12T10:00:50Z","down_duration_s":10,"last_network":null,"precursor":null}"#
        let off = try #require(try Self.decode(Self.line(offline: obj)).link.offline)
        #expect(off.lastNetwork == nil)
        #expect(off.knownLastNetwork == nil)
        #expect(off.precursor == nil)
        #expect(off.precursorSummary == nil, "no precursor, nothing to say about one")
        #expect(off.statusLine == "Offline for 10s", "no network clause rather than a blank or wrong one")
    }

    @Test func aCliWithoutTheSummaryFieldShowsNoSentence() throws {
        // An older CLI sends the precursor but not the sentence about it; the
        // app has no copy of its own to fall back to, so it shows nothing.
        let obj = #"{"reason":"wifi-not-joined","down_since":"2026-10-12T10:00:00Z","down_duration_s":60,"last_network":"Home","precursor":"router-unreachable"}"#
        let off = try #require(try Self.decode(Self.line(offline: obj)).link.offline)
        #expect(off.precursor == "router-unreachable")
        #expect(off.precursorSummary == nil)
    }

    @Test func aMalformedSummaryDoesNotCostTheOtherFields() throws {
        let obj = #"{"reason":"wifi-not-joined","down_duration_s":60,"last_network":"Home","precursor":"router-unreachable","precursor_summary":42}"#
        let off = try #require(try Self.decode(Self.line(offline: obj)).link.offline)
        #expect(off.precursorSummary == nil)
        #expect(off.lastNetwork == "Home")
        #expect(off.downDurationS == 60)
    }

    @Test func carryNetworkDecodesFromStatusAndIsNilWhenAbsent() throws {
        let with = try Self.decode(Self.line(offline: Self.offlineObject))
        #expect(with.status.carryNetwork == "Home")
        let without = try Self.decode(Self.line(offline: Self.offlineObject)
            .replacingOccurrences(of: #","carry_network":"Home""#, with: ""))
        #expect(without.status.carryNetwork == nil)
    }

    @Test func partialBlockKeepsWhatIsThere() throws {
        let off = try #require(try Self.decode(Self.line(offline: #"{"reason":"wifi-off"}"#)).link.offline)
        #expect(off.reason == "wifi-off")
        #expect(off.downDurationS == nil && off.lastNetwork == nil)
        #expect(off.statusLine == nil)
    }

    @Test func malformedFieldsAreDroppedIndividually() throws {
        // A string where a number belongs must not cost the sample, nor the
        // other fields of the block.
        let obj = #"{"reason":"wifi-not-joined","down_since":"2026-10-12T10:00:00Z","down_duration_s":"soon","last_network":"Home","precursor":7}"#
        let s = try Self.decode(Self.line(offline: obj))
        let off = try #require(s.link.offline)
        #expect(off.reason == "wifi-not-joined")
        #expect(off.downDurationS == nil)
        #expect(off.lastNetwork == "Home")
        #expect(off.precursor == nil)
        #expect(off.statusLine == "Last connected to Home")
        #expect(s.status.rules == ["N1", "WJ-1"])
    }

    @Test(arguments: ["[]", "\"offline\"", "42", "true"])
    func nonObjectBlockDropsTheBlockNotTheSample(_ junk: String) throws {
        let s = try Self.decode(Self.line(offline: junk))
        #expect(s.link.offline == nil)
        #expect(s.link.up == false)
        #expect(s.status.rules == ["N1", "WJ-1"])
    }

    @Test func blankNetworkNamesAreNotKnown() {
        for blank in ["", " ", "\n\t "] {
            var off = MonitorSample.OfflineContext(reason: nil, downSince: nil, downDurationS: 30,
                                                   lastNetwork: blank, precursor: nil)
            #expect(off.knownLastNetwork == nil, "\(blank.debugDescription) is not a network")
            #expect(off.statusLine == "Offline for 30s")
            off.downDurationS = nil
            #expect(off.statusLine == nil)
        }
    }

    @Test func negativeDurationIsNotShown() {
        let off = MonitorSample.OfflineContext(reason: nil, downSince: nil, downDurationS: -5,
                                               lastNetwork: "Home", precursor: nil)
        #expect(off.formattedDuration == nil)
        #expect(off.statusLine == "Last connected to Home")
    }

    // MARK: reason_label: the CLI's caption, never a mapping in the app

    @Test func reasonLabelIsTheCLIsCaptionVerbatim() throws {
        let off = try #require(try Self.decode(Self.line(offline: Self.offlineObject)).link.offline)
        #expect(off.reasonLabel == "Not connected")
        #expect(off.knownReasonLabel == "Not connected")
        // The label is what is shown, whatever the reason: the app has no
        // table from reason to words.
        let odd = try #require(try Self.decode(Self.line(
            offline: #"{"reason":"something-new","reason_label":"Cable unplugged"}"#)).link.offline)
        #expect(odd.knownReasonLabel == "Cable unplugged")
    }

    @Test func aCliWithoutReasonLabelOrWithANullOneShowsNoCaption() throws {
        // An older CLI sends the reason but no caption: the card falls back
        // to its neutral wording rather than mapping "wifi-off" itself.
        let old = try #require(try Self.decode(Self.line(
            offline: #"{"reason":"wifi-off","down_duration_s":60}"#)).link.offline)
        #expect(old.reason == "wifi-off")
        #expect(old.knownReasonLabel == nil)
        let null = try #require(try Self.decode(Self.line(
            offline: #"{"reason":"no-route","reason_label":null}"#)).link.offline)
        #expect(null.knownReasonLabel == nil)
    }

    @Test(arguments: ["", "  ", "\n"])
    func aBlankReasonLabelIsNoCaption(_ blank: String) {
        let off = MonitorSample.OfflineContext(reason: "wifi-off", downSince: nil, downDurationS: nil,
                                               lastNetwork: nil, precursor: nil, reasonLabel: blank)
        #expect(off.knownReasonLabel == nil)
    }

    @Test func aMalformedReasonLabelDoesNotCostTheOtherFields() throws {
        let off = try #require(try Self.decode(Self.line(
            offline: #"{"reason":"wifi-off","reason_label":7,"down_duration_s":60,"last_network":"Home"}"#)).link.offline)
        #expect(off.knownReasonLabel == nil)
        #expect(off.downDurationS == 60)
        #expect(off.lastNetwork == "Home")
    }

    // MARK: the repair button comes from the rules catalog

    static func catalog(_ rules: String) throws -> RulesCatalog {
        try JSONDecoder().decode(RulesCatalog.self, from: Data(#"{"schema":6,"version":"x","rules":[\#(rules)]}"#.utf8))
    }

    @Test func theCatalogsRepairsDecodeAndDecideWhichFiringRuleOffersReconnect() throws {
        let cat = try Self.catalog(#"""
        {"id":"N1","title":"No network connection at all"},
        {"id":"WJ-1","title":"t","repairs":["reconnect-wifi"]},
        {"id":"DH-3","title":"t","repairs":["reconnect-wifi"]},
        {"id":"WF-1","title":"t","repairs":["reconnect-wifi"]},
        {"id":"SOCK-1","title":"t","repairs":["quit-app","restart-mac"]}
        """#)
        #expect(cat["WJ-1"]?.repairs == ["reconnect-wifi"])
        #expect(cat["N1"]?.repairs == nil)
        #expect(cat.firstRule(offering: "reconnect-wifi", among: ["N1", "WJ-1"]) == "WJ-1")
        #expect(cat.firstRule(offering: "reconnect-wifi", among: ["N1", "DH-3"]) == "DH-3")
        #expect(cat.firstRule(offering: "reconnect-wifi", among: ["N1", "WF-1"]) == "WF-1")
        // No firing rule offers it: no button, however the rules are named.
        #expect(cat.firstRule(offering: "reconnect-wifi", among: ["N1"]) == nil)
        #expect(cat.firstRule(offering: "reconnect-wifi", among: ["SOCK-1"]) == nil)
        #expect(cat.firstRule(offering: "reconnect-wifi", among: []) == nil)
    }

    @Test func anOlderCatalogWithoutRepairsOffersNoReconnectButStillDecodes() throws {
        let cat = try Self.catalog(#"{"id":"WJ-1","title":"Wi-Fi dropped"},{"id":"N1","title":"No network"}"#)
        #expect(cat["WJ-1"]?.title == "Wi-Fi dropped")
        #expect(cat.firstRule(offering: "reconnect-wifi", among: ["N1", "WJ-1"]) == nil)
        // A malformed list costs that field, not the rule or the catalog.
        let bad = try Self.catalog(#"{"id":"WJ-1","title":"t","repairs":"reconnect-wifi"}"#)
        #expect(bad["WJ-1"]?.title == "t")
        #expect(bad["WJ-1"]?.repairs == nil)
    }

    @Test @MainActor func theCoordinatorOffersNoReconnectUntilTheCatalogHasLoaded() {
        // No catalog loaded (as at launch or against an old CLI): the card
        // draws no Reconnect button and keeps no list of rules that get one.
        // (A default coordinator: auto-reconnect is off and nothing starts.)
        let c = HopwatchCoordinator()
        #expect(c.reconnectRule(amongFiring: ["N1", "WJ-1"]) == nil)
    }

    @Test func liveJitterIsNilForADecodedOfflineSample() throws {
        // Reads `link.offline != nil`; it used to rely on `interface`, which
        // the monitor does not send once the route is gone.
        var s = try Self.decode(Self.line(offline: Self.offlineObject))
        s.jitterMs = 4
        #expect(s.liveJitterMs == nil)
    }
}
